    Source: packages/compose-gen/specs/organisms/member-row.json
    One member of TeamGrid beside a small portrait: the name, the role, then the department and the place (detailed, directory), the bio (detailed) and the skills (detailed, list).
    Props (p): member, depts, layout. *}
{var $v_member = ($p['member'] ?? null)}
{var $v_depts = ($p['depts'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'list')}
{capture $c_11}
  {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_member, ['name']), 'ratio' => '1/1', 'className' => og_cnv([og_cnv([(og_t(og_eq($v_layout, 'detailed')) ? 'size-16' : 'size-12'), 'shrink-0'])])]])|noescape}
  {capture $c_10}
    {capture $c_3}
      {capture $c_1}
        {=og_text(og_get($v_member, ['name']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'base', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
      {capture $c_2}
        {=og_text(og_get($v_member, ['role']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
    {/capture}
    {=og_include('compose/Stack.latte', ['gap' => '0', 'children' => (string) $c_3])|noescape}
    {if og_t(!(og_eq($v_layout, 'list')))}
      {capture $c_6}
        {capture $c_4}
          {=og_text(og_at($v_depts, og_get($v_member, ['dept'])))}
        {/capture}
        {=og_include('compose/Badge.latte', ['variant' => 'outline', 'size' => 'sm', 'children' => (string) $c_4])|noescape}
        {=og_include('icons/LucideIcon.latte', ['name' => 'map-pin', 'size' => 16])|noescape}
        {capture $c_5}
          {=og_text(og_get($v_member, ['location']))}
        {/capture}
        {=og_include('compose/Inline.latte', ['children' => (string) $c_5])|noescape}
      {/capture}
      {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'class' => 'flex-wrap text-xs text-muted-foreground', 'children' => (string) $c_6])|noescape}
    {/if}
    {if og_t(og_eq($v_layout, 'detailed'))}
      {capture $c_7}
        {=og_text(og_get($v_member, ['bio']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_7])|noescape}
    {/if}
    {if og_t(!(og_eq($v_layout, 'directory')))}
      {capture $c_9}
        {foreach og_l(og_get($v_member, ['skills'])) as $v_k}
          {capture $c_8}
            {=og_text($v_k)}
          {/capture}
          {=og_include('compose/Badge.latte', ['variant' => 'secondary', 'size' => 'sm', 'children' => (string) $c_8])|noescape}
        {/foreach}
      {/capture}
      {=og_include('compose/Group.latte', ['gap' => '2', 'class' => 'flex-wrap', 'children' => (string) $c_9])|noescape}
    {/if}
  {/capture}
  {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => 'min-w-0 flex-1', 'children' => (string) $c_10])|noescape}
{/capture}
{=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'start', 'class' => og_s((og_t(og_eq($v_layout, 'detailed')) ? 'rounded bg-card inset-ring inset-ring-border flex-col p-6' : (og_t(og_eq($v_layout, 'directory')) ? 'rounded bg-card inset-ring inset-ring-border p-4' : 'border-b border-border pb-4'))), 'attrs' => og_attrs(['data-slot', 'item']), 'children' => (string) $c_11])|noescape}
